import it.servizidigitali.gestionebandi.operatore.frontend.enums.CamundaCodiciOperazioniUtente;
import it.servizidigitali.gestionebandi.operatore.frontend.enums.CustomProcessVariablesBandi;
import it.servizidigitali.gestionebandi.operatore.frontend.service.ScrivaniaOperatoreBandiFrontendService;
import it.servizidigitali.gestionebandi.service.DomandaBandoLocalService;
import it.servizidigitali.gestionebandi.service.GraduatoriaBandoLocalService;

@Component(immediate = true, service = MVCActionCommand.class, property = {
        "javax.portlet.name=" + ScrivaniaOperatoreBandiPortletKeys.SCRIVANIA_OPERATORE_BANDI,
        "mvc.command.name=" + ScrivaniaOperatoreBandiPortletKeys.RIELABORA_VALUTAZIONE_AVVISI_SPORTELLO_ACTION,
})
public class RielaboraValutazioneAvvisiSportelloActionCommand extends BaseMVCActionCommand{

    private static final Log _log = LogFactoryUtil.getLog(RielaboraValutazioneActionCommand.class);

    @Reference
    private DomandaBandoLocalService domandaBandoLocalService;

    @Reference
    private GroupLocalService groupLocalService;

    @Reference
    private CamundaClient camundaClient;

    @Reference
    private ScrivaniaOperatoreBandiFrontendService scrivaniaOperatoreBandiFrontendService;

    @Reference
    private GraduatoriaBandoLocalService graduatoriaBandoLocalService;

    @Reference
    private BandoLocalService bandoLocalService;

    @Reference
    private TipologiaBandoLocalService tipologiaBandoLocalService;

    @Override
    protected void doProcessAction(ActionRequest actionRequest, ActionResponse actionResponse) throws Exception {

        long domandaBandoId = ParamUtil.getLong(actionRequest, "domandaBandoId");
        MutableRenderParameters renderParameters = actionResponse.getRenderParameters();
        long bandoId = 0;

        if(domandaBandoId>0) {
            DomandaBando domandaBando = domandaBandoLocalService.getDomandaBando(domandaBandoId);
            Bando bando = bandoLocalService.fetchBando(domandaBando.getBandoId());
            TipologiaBando tipologiaBando = tipologiaBandoLocalService.getTipologiaBando(bando.getTipologiaBandoId());
            TipologiaBandoEnum tipologiaBandoEnum = TipologiaBandoEnum.valueOf(tipologiaBando.getCodice());

            if(Validator.isNotNull(domandaBando)) {
                bandoId = domandaBando.getBandoId();
                long groupId = domandaBando.getGroupId();
                long organizationId = groupLocalService.getGroup(groupId).getOrganizationId();

                String tenantId = String.valueOf(organizationId);
                List<ProcessInstance> processInstanceByBusinessKey = camundaClient.getProcessInstanceByBusinessKey(tenantId, String.valueOf(domandaBando.getDomandaBandoId()));
                if (processInstanceByBusinessKey.size() != 1) {
                    _log.error("Impossibile individuare univocamente l'istanza di processo.");
                }else {
                    if (tipologiaBandoEnum.equals(TipologiaBandoEnum.RICHIESTA_CONTRIBUTI)) {
                        domandaBando.setImportoAssegnato(null);
                        domandaBandoLocalService.updateDomandaBando(domandaBando);
                    }
                    camundaClient.updateProcessInstanceVariableByBusinessKey(domandaBando.getProcessInstanceId(), CamundaCodiciOperazioniUtente.ESITO_LAVORAZIONE.getValue(), CamundaActionsVariable.VAR_INSERIMENTO_VALUTAZIONI.getValue(), "string");
                    camundaClient.correlateMessage(tenantId, CustomProcessVariablesBandi.INVIO_A_RIESAME.name(), String.valueOf(domandaBando.getDomandaBandoId()));
                    scrivaniaOperatoreBandiFrontendService.aggiornaConvalidaValutazioneByDomandaBandoId(domandaBandoId, false);
                }
            }
        }

        renderParameters.setValue("bandoId", String.valueOf(bandoId));
        renderParameters.setValue("mvcRenderCommandName", ScrivaniaOperatoreBandiPortletKeys.VISUALIZZA_LISTA_DOMANDE_RENDER);

    }

}

