148				return;
149			}
150	
151			_log.debug("Scheduled task executed AVVIO ISTANZA BANDI...");
152	
153			List<Bando> bandi = bandoLocalService.getBandos(QueryUtil.ALL_POS, QueryUtil.ALL_POS);
154	
155			for (Bando bando : bandi) {
156				try {
157					List<DomandaBando> domandeBando = domandaBandoLocalService
158							.getListaDomandeBandoOrdinate(bando.getBandoId(), StatoDomandaBandoEnum.NUOVA.name());
159					if (domandeBando.isEmpty()) {
160						_log.debug("Nessuna domanda da elaborare per bando " + bando.getCodice());
161					}
162	
163					for (DomandaBando domanda : domandeBando) {
164						avviaProcesso(domanda);
165					}
166				} catch (Exception e) {
167					_log.error("Fermato avvii processi per bando " + bando.getCodice(), e);
168				}
169			}
170		}
