371		@Activate
372		@Modified
373		protected void activate(Map<String, Object> properties) throws SchedulerException {
374	
375			// extract the cron expression from the properties
376			try {
377				avvioIstanzaProcessoSchedulerConfiguration = ConfigurableUtil.createConfigurable(IstanzaProcessoBandiSchedulerConfiguration.class, properties);
378				camundaConfiguration = ConfigurableUtil.createConfigurable(CamundaConfiguration.class, properties);
379	
380				if (!avvioIstanzaProcessoSchedulerConfiguration.avvioIstanzaProcessoBandiSchedulerEnabled()) {
381					_log.info("Diattivazione scheduler " + this.getClass().getSimpleName());
382					deactivate();
383					return;
384				}
385	
386				String cronExpression = avvioIstanzaProcessoSchedulerConfiguration.avvioIstanzaProcessoBandiSchedulerCronExpression();
387	
388				_log.info("Attivazione scheduler " + this.getClass().getSimpleName() + " - cronExpression: " + cronExpression);
389	
390				// create a new trigger definition for the job.
391				String listenerClass = getClass().getName();
392				Trigger jobTrigger = _triggerFactory.createTrigger(listenerClass, listenerClass, new Date(), null, cronExpression);
393	
394				// wrap the current scheduler entry in our new wrapper.
395				// use the persisted storaget type and set the wrapper back to the class field.
396				_schedulerEntryImpl = new SchedulerEntryImpl(getClass().getName(), jobTrigger);
397	
398				// if we were initialized (i.e. if this is called due to CA modification)
399				if (_initialized) {
400					// first deactivate the current job before we schedule.
401					deactivate();
402				}
403	
404				// register the scheduled task
405				_schedulerEngineHelper.register(this, _schedulerEntryImpl, DestinationNames.SCHEDULER_DISPATCH);
406	
407				// set the initialized flag.
408				_initialized = true;
409			}
410			catch (Exception e) {
411				_log.error(e);
412				deactivate();
413			}
414		}
415	
416		@Deactivate
417		protected void deactivate() {
418			// if we previously were initialized
419			if (_initialized) {
420				// unschedule the job so it is cleaned up
421				try {
422					_schedulerEngineHelper.unschedule(_schedulerEntryImpl, getStorageType());
423				}
424				catch (SchedulerException se) {
425					if (_log.isWarnEnabled()) {
426						_log.warn("Unable to unschedule trigger", se);
427					}
428				}
429	
430				// unregister this listener
431				_schedulerEngineHelper.unregister(this);
432			}
433	
434			// clear the initialized flag
435			_initialized = false;
436		}
