480		protected String convertiSecondiInISO8601(long secondi) {
481			long anni = secondi / 31536000;
482			long mesi = (secondi % 31536000) / 2592000;
483			long giorni = (secondi % 2592000) / 86400;
484			long ore = (secondi % 86400) / 3600;
485			long minuti = (secondi % 3600) / 60;
486			long secondiRimasti = secondi % 60;
487	
488			StringBuilder sb = new StringBuilder();
489			Formatter formatter = new Formatter(sb, Locale.ITALY);
490			formatter.format("P%dY%dM%dDT%dH%dM%dS", anni, mesi, giorni, ore, minuti, secondiRimasti);
491	
492			return sb.toString();
493		}
