public class AvvioIstanzaProcessoBandiScheduler extends BaseMessageListener {

	private static final String ALLEGATO_PDF_FIRMATO = "allegato-pdf-firmato";

	private static final Log _log = LogFactoryUtil.getLog(AvvioIstanzaProcessoBandiScheduler.class);

	private volatile boolean _initialized;
	private TriggerFactory _triggerFactory;
	private SchedulerEngineHelper _schedulerEngineHelper;
	private SchedulerEntryImpl _schedulerEntryImpl = null;

	private volatile IstanzaProcessoBandiSchedulerConfiguration avvioIstanzaProcessoSchedulerConfiguration;
	private volatile CamundaConfiguration camundaConfiguration;


	@Reference
	private DomandaBandoLocalService domandaBandoLocalService;

	@Reference
	private BandoLocalService bandoLocalService;

	@Reference
	private SottoOrganizzazioneLocalService sottoOrganizzazioneLocalService;

	@Reference
	private AllegatoDomandaBandoLocalService allegatoDomandaBandoLocalService;

	@Reference
	private ProcessoLocalService processoLocalService;

	@Reference
	private CamundaClient camundaClient;

	@Reference
	private SiteUtility siteUtility;

	@Reference
	private OrganizationLocalService organizationLocalService;

	@Reference
	private OrganizationUtility organizationUtility;

	@Reference
	private UserLocalService userLocalService;

	@Reference
	private TipologiaBandoLocalService tipologiaBandoLocalService;

	@Reference
	private TermineBandoLocalService termineBandoLocalService;

	@Reference
	private DomandaBandoDatoAggiuntivoLocalService domandaBandoDatoAggiuntivoLocalService;


	@Override
	protected void doReceive(Message message) throws Exception {

		if (!camundaConfiguration.integrationEnabled()) {
			return;
		}

		_log.debug("Scheduled task executed AVVIO ISTANZA BANDI...");

		List<Bando> bandi = bandoLocalService.getBandos(QueryUtil.ALL_POS, QueryUtil.ALL_POS);

		for (Bando bando : bandi) {
			try {
				List<DomandaBando> domandeBando = domandaBandoLocalService
						.getListaDomandeBandoOrdinate(bando.getBandoId(), StatoDomandaBandoEnum.NUOVA.name());
				if (domandeBando.isEmpty()) {
					_log.debug("Nessuna domanda da elaborare per bando " + bando.getCodice());
				}

				for (DomandaBando domanda : domandeBando) {
					avviaProcesso(domanda);
				}
			} catch (Exception e) {
				_log.error("Fermato avvii processi per bando " + bando.getCodice(), e);
			}
		}
	}

	private void avviaProcesso(DomandaBando domanda) throws Exception {
		ObjectMapper objectMapper = new ObjectMapper();

		long businessKey = domanda.getDomandaBandoId();
		if (Validator.isNotNull(domanda.getProcessInstanceId())) {
			throw new Exception("Esiste già una istanza di processo assegnata alla richiesta: " + businessKey);
		}

		// verifica processo già avviato
		long groupId = domanda.getGroupId();

		Organization siteOrganization = organizationUtility.getSiteOrganization(groupId);

		long organizationId = siteOrganization.getOrganizationId();

		String tenantId = String.valueOf(organizationId);
		boolean existProcessByBusinessKey = camundaClient.existProcessByBusinessKey(tenantId, String.valueOf(businessKey));

		if (existProcessByBusinessKey) {
			throw new Exception("Esiste già una istanza di processo attiva per organizationId " + organizationId + " e businessKey " + businessKey);
		}

		User userRichiesta = userLocalService.getUserByScreenName(domanda.getCompanyId(), domanda.getCodiceFiscale().toLowerCase());

		PrincipalThreadLocal.setName(userRichiesta.getUserId());
		PermissionChecker permissionChecker = PermissionCheckerFactoryUtil.create(userRichiesta);
		PermissionThreadLocal.setPermissionChecker(permissionChecker);

		Organization organization = organizationLocalService.getOrganization(organizationId);
		Serializable codiceIPACustomAttribute = organization.getExpandoBridge().getAttribute(OrganizationCustomAttributes.CODICE_IPA.getNomeAttributo());

		String codiceIPA = null;
		if (codiceIPACustomAttribute != null) {
			codiceIPA = (String) codiceIPACustomAttribute;
		}

		Bando bando = bandoLocalService.getBando(domanda.getBandoId());
		long processoId = bando.getProcessoId();
		if (Validator.isNull(processoId)) {
			throw new Exception("Impossibile avviare il workflow: Processo BPM mancante.");
		}

		Processo processo = processoLocalService.fetchProcesso(processoId);
		if (Validator.isNull(processo) || !processo.isAttivo()) {
			throw new Exception("Impossibile avviare il workflow: Processo NON trovato.");
		}

		List<SottoOrganizzazione> sottoOrganizzazioni = sottoOrganizzazioneLocalService.getListSottoOrganizzazioneByBandoId(domanda.getBandoId());
		if (sottoOrganizzazioni != null) {
			for (SottoOrganizzazione sottoOrganizzazione : sottoOrganizzazioni) {
				String candidateGroup = String.valueOf(sottoOrganizzazione.getSubOrganizationId());
				boolean existsGroup = camundaClient.existsGroup(candidateGroup);
				if (!existsGroup) {
					throw new Exception("Impossibile assegnare il Gruppo Destinatario.");
				}
			}
		}

		// Allegati
		String allegatiJson = "";
		List<AllegatoDomandaBando> allegatiDomanda = allegatoDomandaBandoLocalService.getListaAllegatiByDomandaBandoId(domanda.getDomandaBandoId());
		List<FileAllegato> datiFileAllegati = getAllegati(allegatiDomanda);
		if (datiFileAllegati != null) {
			allegatiJson = objectMapper.writerWithDefaultPrettyPrinter().writeValueAsString(datiFileAllegati);
		}

		// PDF principale
		String pdfFirmatoJson = "";
		List<AllegatoDomandaBando> allegatiDomandaByDomandaBandoIdPrincipale = allegatoDomandaBandoLocalService.getListaAllegatiByDomandaBandoIdAndPrincipale(domanda.getDomandaBandoId(),
				true);

		if (allegatiDomandaByDomandaBandoIdPrincipale != null && !allegatiDomandaByDomandaBandoIdPrincipale.isEmpty()) {
			AllegatoDomandaBando allegatoPrincipaleBando = allegatiDomandaByDomandaBandoIdPrincipale.get(0);
			FileAllegato allegatoPrincipale = getAllegatoPrincipale(allegatoPrincipaleBando);
			if (allegatoPrincipale != null) {
				pdfFirmatoJson = objectMapper.writerWithDefaultPrettyPrinter().writeValueAsString(allegatoPrincipale);
			}
		}

		Map<String, Object> variables = new HashMap<>();
		variables.put(GestioneBandiCommonConstants.ID_DOMANDA_BANDO, domanda.getDomandaBandoId());
		for (SottoOrganizzazione sottoOrganizzazione : sottoOrganizzazioni) {
			String candidateGroup = String.valueOf(sottoOrganizzazione.getSubOrganizationId());
			variables.put(sottoOrganizzazione.getCodice(), candidateGroup);
		}

		// Termini
		List<TermineBando> listaTermineBando = termineBandoLocalService.getTermineBandoByBandoId(domanda.getBandoId());
		for (TermineBando termineBando : listaTermineBando) {
			if (Validator.isNotNull(termineBando.getDataScadenza())) {
				SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss'Z'");
				String dataScadenza = sdf.format(termineBando.getDataScadenza());
				variables.put(termineBando.getCodice(), dataScadenza);
			} else {
				variables.put(termineBando.getCodice(), convertiSecondiInISO8601(termineBando.getSecondi()));
			}
		}
		List<DomandaBandoDatoAggiuntivo> domandaBandoDatoAggiuntivos = domandaBandoDatoAggiuntivoLocalService.getDomandaBandoDatoAggiuntivoByDomandaBandoIdAndChiave(List.of(domanda.getDomandaBandoId()),
				List.of(DatoAggiuntivoChiave.CHIUSURA_NEGATIVA_AUTOMATICA.name()));

		if(ListUtil.isNotNull(domandaBandoDatoAggiuntivos) && ListUtil.isNotEmpty(domandaBandoDatoAggiuntivos)){
			if(Validator.isNotNull(domandaBandoDatoAggiuntivos.get(0))){
				DomandaBandoDatoAggiuntivo domandaBandoDatoAggiuntivo = domandaBandoDatoAggiuntivos.get(0);

				if(Validator.isNotNull(domandaBandoDatoAggiuntivo.getValore()) && domandaBandoDatoAggiuntivo.getValore().equalsIgnoreCase(Boolean.TRUE.toString())){
					variables.put(GestioneBandiCommonConstants.CHIUSURA_NEGATIVA_AUTOMATICA, Boolean.TRUE.toString());
					variables.put(CustomProcessVariables.ESITO_PROCEDIMENTO, "NEGATIVO");
				}
			}
		}

		//TODO: aggiungere le variabili necessarie
		//variables.put("ESITO_LAVORAZIONE","CONCESSIONE");

		TipologiaBando tipologiaBando = tipologiaBandoLocalService.getTipologiaBando(bando.getTipologiaBandoId());
		variables.put(GestioneBandiCommonConstants.TIPOLOGIA_BANDO_DOMANDA, tipologiaBando.getCodice());

		variables.put(CustomProcessVariables.DENOMINAZIONE_RICHIEDENTE, userRichiesta.getFullName());
		variables.put(CustomProcessVariables.COD_FISCALE_RICHIEDENTE, domanda.getCodiceFiscale().toUpperCase());
		variables.put(CustomProcessVariables.EMAIL_RICHIEDENTE, domanda.getEmail());
		variables.put(CustomProcessVariables.PARTITA_IVA_RICHIEDENTE, domanda.getPartitaIva());

//									variables.put(CustomProcessVariables.FILE_ALLEGATI, allegatiJson);
		variables.put(CustomProcessVariables.NOME_FILE_FIRMATO, ALLEGATO_PDF_FIRMATO);
		variables.put(CustomProcessVariables.PDF_FIRMATO, pdfFirmatoJson);

		variables.put(CustomProcessVariables.CODICE_IPA_COMUNE, codiceIPA);
		variables.put(CustomProcessVariables.DENOMINAZIONE_COMUNE, organization.getName());

		variables.put(GestioneBandiCommonConstants.DATA_CREAZIONE_DOMANDA, domanda.getCreateDate());
		variables.put(GestioneBandiCommonConstants.STATO_DOMANDA, domanda.getStato());
		variables.put(GestioneBandiCommonConstants.INVIO_GUEST, String.valueOf(domanda.getInvioGuest()));
		variables.put(GestioneBandiCommonConstants.RAGIONE_SOCIALE, domanda.getRagioneSociale());
		variables.put(GestioneBandiCommonConstants.DATA_CREAZIONE_DOMANDA_SEARCH, domanda.getCreateDate().getTime());
		variables.put(GestioneBandiCommonConstants.DATA_INVIO_DOMANDA, domanda.getDataArrivo());
		variables.put(GestioneBandiCommonConstants.DATA_INVIO_DOMANDA_SEARCH, domanda.getDataArrivo().getTime());
		variables.put(CustomProcessVariables.TIPO_INTEGRAZIONE, "");
		variables.put(CustomProcessVariables.CODICE_BANDO, bando.getCodice());

		variables.put(GestioneBandiCommonConstants.CODICE_AOO, bando.getCodiceAOO());
		variables.put(GestioneBandiCommonConstants.CODICE_UO, bando.getCodiceUO());

		variables.put(GestioneBandiCommonConstants.PROTOCOLLA_INTEGRAZIONI, bando.getProtocollaIntegrazioni());
		variables.put(CustomProcessVariables.CAMBIO_STATO_WORKFLOW, true);
		variables.put(GestioneBandiCommonConstants.SUPPORTA_CHIUDI_PRATICA_ESITO_NEGATIVO, true);

		String processDefinitionTenantId = tenantId;

		boolean isBackofficeMainSiteProcess = siteUtility.isBackofficeMainSite(processo.getGroupId(), processo.getCompanyId());

		if (isBackofficeMainSiteProcess) {
			processDefinitionTenantId = null;
		}

		String processInstanceId = camundaClient.startProcessInstance(tenantId, processDefinitionTenantId, processo.getCodice(), String.valueOf(businessKey), variables);
		domandaBandoLocalService.updateProcessInstanceIdDomandaBando(domanda.getDomandaBandoId(), processInstanceId);
	}

	/**
	 * @param allegatoPrincipaleRichiesta
	 * @return
	 */
	private FileAllegato getAllegatoPrincipale(AllegatoDomandaBando allegatoPrincipaleRichiesta) {
		if (allegatoPrincipaleRichiesta != null) {
			FileAllegato datiFileAllegato = new FileAllegato();
			datiFileAllegato.setDataInserimento(allegatoPrincipaleRichiesta.getCreateDate());
			datiFileAllegato.setFileName(allegatoPrincipaleRichiesta.getNome());
			datiFileAllegato.setId(allegatoPrincipaleRichiesta.getAllegatoDomandaBandoId());
			datiFileAllegato.setIdDocumentale(allegatoPrincipaleRichiesta.getIdDocumentale());
			datiFileAllegato.setIdTemporaneo(ALLEGATO_PDF_FIRMATO);
			datiFileAllegato.setIdDefinizioneAllegato(-1);
			return datiFileAllegato;
		}
		return null;
	}

	/**
	 * @param allegatiDomanda
	 * @return
	 */
	private List<FileAllegato> getAllegati(List<AllegatoDomandaBando> allegatiDomanda) {
		List<FileAllegato> results = null;
		if (allegatiDomanda != null && !allegatiDomanda.isEmpty()) {
			results = new ArrayList<FileAllegato>();
			for (AllegatoDomandaBando allegatoDomanda : allegatiDomanda) {
				if (!allegatoDomanda.isPrincipale()) {
					FileAllegato datiFileAllegato = new FileAllegato();
					datiFileAllegato.setDataInserimento(allegatoDomanda.getCreateDate());
					datiFileAllegato.setFileName(allegatoDomanda.getNome());
					datiFileAllegato.setId(allegatoDomanda.getAllegatoDomandaBandoId());
					datiFileAllegato.setIdDocumentale(allegatoDomanda.getIdDocumentale());
					datiFileAllegato.setIdDefinizioneAllegato(allegatoDomanda.getDefinizioneAllegatoId());
					results.add(datiFileAllegato);
				}
			}
		}
		return results;
	}

	@Activate
	@Modified
	protected void activate(Map<String, Object> properties) throws SchedulerException {

		// extract the cron expression from the properties
		try {
			avvioIstanzaProcessoSchedulerConfiguration = ConfigurableUtil.createConfigurable(IstanzaProcessoBandiSchedulerConfiguration.class, properties);
			camundaConfiguration = ConfigurableUtil.createConfigurable(CamundaConfiguration.class, properties);

			if (!avvioIstanzaProcessoSchedulerConfiguration.avvioIstanzaProcessoBandiSchedulerEnabled()) {
				_log.info("Diattivazione scheduler " + this.getClass().getSimpleName());
				deactivate();
				return;
			}

			String cronExpression = avvioIstanzaProcessoSchedulerConfiguration.avvioIstanzaProcessoBandiSchedulerCronExpression();

			_log.info("Attivazione scheduler " + this.getClass().getSimpleName() + " - cronExpression: " + cronExpression);

			// create a new trigger definition for the job.
			String listenerClass = getClass().getName();
			Trigger jobTrigger = _triggerFactory.createTrigger(listenerClass, listenerClass, new Date(), null, cronExpression);

			// wrap the current scheduler entry in our new wrapper.
			// use the persisted storaget type and set the wrapper back to the class field.
			_schedulerEntryImpl = new SchedulerEntryImpl(getClass().getName(), jobTrigger);

			// if we were initialized (i.e. if this is called due to CA modification)
			if (_initialized) {
				// first deactivate the current job before we schedule.
				deactivate();
			}

			// register the scheduled task
			_schedulerEngineHelper.register(this, _schedulerEntryImpl, DestinationNames.SCHEDULER_DISPATCH);

			// set the initialized flag.
			_initialized = true;
		}
		catch (Exception e) {
			_log.error(e);
			deactivate();
		}
	}

	@Deactivate
	protected void deactivate() {
		// if we previously were initialized
		if (_initialized) {
			// unschedule the job so it is cleaned up
			try {
				_schedulerEngineHelper.unschedule(_schedulerEntryImpl, getStorageType());
			}
			catch (SchedulerException se) {
				if (_log.isWarnEnabled()) {
					_log.warn("Unable to unschedule trigger", se);
				}
			}

			// unregister this listener
			_schedulerEngineHelper.unregister(this);
		}

		// clear the initialized flag
		_initialized = false;
	}

	/**
	 * getStorageType: Utility method to get the storage type from the scheduler entry wrapper.
	 *
	 * @return StorageType The storage type to use.
	 */
	protected StorageType getStorageType() {
		if (_schedulerEntryImpl instanceof StorageTypeAware) {
			return ((StorageTypeAware) _schedulerEntryImpl).getStorageType();
		}

		return StorageType.MEMORY_CLUSTERED;
	}

	/**
	 * setModuleServiceLifecycle: So this requires some explanation...
	 *
	 * OSGi will start a component once all of it's dependencies are satisfied. However, there are
	 * times where you want to hold off until the portal is completely ready to go.
	 *
	 * This reference declaration is waiting for the ModuleServiceLifecycle's PORTAL_INITIALIZED
	 * component which will not be available until, surprise surprise, the portal has finished
	 * initializing.
	 *
	 * With this reference, this component activation waits until portal initialization has
	 * completed.
	 *
	 * @param moduleServiceLifecycle
	 */
	@Reference(target = ModuleServiceLifecycle.PORTAL_INITIALIZED, unbind = "-")
	protected void setModuleServiceLifecycle(ModuleServiceLifecycle moduleServiceLifecycle) {
	}

	@Reference(unbind = "-")
	protected void setTriggerFactory(TriggerFactory triggerFactory) {
		_triggerFactory = triggerFactory;
	}

	@Reference(unbind = "-")
	protected void setSchedulerEngineHelper(SchedulerEngineHelper schedulerEngineHelper) {
		_schedulerEngineHelper = schedulerEngineHelper;
	}

	protected String convertiSecondiInISO8601(long secondi) {
		long anni = secondi / 31536000;
		long mesi = (secondi % 31536000) / 2592000;
		long giorni = (secondi % 2592000) / 86400;
		long ore = (secondi % 86400) / 3600;
		long minuti = (secondi % 3600) / 60;
		long secondiRimasti = secondi % 60;

		StringBuilder sb = new StringBuilder();
		Formatter formatter = new Formatter(sb, Locale.ITALY);
		formatter.format("P%dY%dM%dDT%dH%dM%dS", anni, mesi, giorni, ore, minuti, secondiRimasti);

		return sb.toString();
	}

}

